import java.util.Scanner;

public class Main {
    static final long INF = 17446744073709551616L;
    static long mod, n, k;
    static long[][] dp = new long[19][300005];
    static long[] fac = new long[300005];
    static long[] inv = new long[300005];

    static long qpow(long a, long b) {
        long res = 1L;
        long base = a;
        while (b > 0) {
            if ((b & 1L) == 1L) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            b >>= 1;
        }
        return res;
    }

    static long combination(int a, int b) {
        return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
    }

    static long compute() {
        int i, j, l;
        fac[0] = 1L;
        long limit = Math.max(n, k);
        for (i = 1; i <= limit; i++) {
            fac[i] = (fac[i - 1] * i) % mod;
        }
        inv[(int)limit] = qpow(fac[(int)limit], mod - 2);
        for (i = (int)limit - 1; i >= 0; i--) {
            inv[i] = (inv[i + 1] * (i + 1)) % mod;
        }
        for (i = 1; i <= n; i++) {
            dp[1][i] = inv[i];
        }
        long answer = (dp[1][(int)n] * combination((int)k, 1)) % mod;
        int t = (int)Math.min(18, k);
        for (i = 2; i <= t; i++) {
            for (j = (int)n; j > 0; j = (j - 1) & (int)n) {
                if (dp[i - 1][j] == 0) continue;
                int r = (int)(n ^ j);
                for (l = r; l > j; l = (l - 1) & r) {
                    dp[i][j ^ l] += dp[i - 1][j] * inv[l];
                    if (dp[i][j ^ l] > INF) dp[i][j ^ l] %= mod;
                }
            }
            for (j = (int)n; j > 0; j = (j - 1) & (int)n) {
                if (dp[i][j] >= mod) dp[i][j] %= mod;
            }
            long res = (dp[i][(int)n] * combination((int)k, i)) % mod;
            res = (res * fac[i]) % mod;
            answer = (answer + res >= mod ? answer + res - mod : answer + res);
        }
        answer = (answer * fac[(int)n]) % mod;
        return answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextLong();
        mod = sc.nextLong();
        long ans = qpow(k, n);
        if (n % 2 == 0) {
            ans = (ans - compute() + mod) % mod;
        }
        System.out.println(ans);
        sc.close();
    }
